package library.dp;
public class EditDistance { public int levenshtein(String a,String b){int[] p=new int[b.length()+1],q=new int[b.length()+1];for(int j=0;j<=b.length();j++)p[j]=j;for(int i=1;i<=a.length();i++){q[0]=i;for(int j=1;j<=b.length();j++)q[j]=Math.min(Math.min(q[j-1]+1,p[j]+1),p[j-1]+(Character.toLowerCase(a.charAt(i-1))==Character.toLowerCase(b.charAt(j-1))?0:1));int[] t=p;p=q;q=t;}return p[b.length()];} public int damerau(String a,String b){int n=a.length(),m=b.length();int[][] d=new int[n+2][m+2];int inf=n+m;d[0][0]=inf;for(int i=0;i<=n;i++){d[i+1][1]=i;d[i+1][0]=inf;}for(int j=0;j<=m;j++){d[1][j+1]=j;d[0][j+1]=inf;}int[] last=new int[65536];for(int i=1;i<=n;i++){int db=0;for(int j=1;j<=m;j++){int i1=last[b.charAt(j-1)];int j1=db;int cost=a.charAt(i-1)==b.charAt(j-1)?0:1;if(cost==0)db=j;d[i+1][j+1]=Math.min(Math.min(d[i][j]+cost,d[i+1][j]+1),Math.min(d[i][j+1]+1,d[i1][j1]+(i-i1-1)+1+(j-j1-1)));}last[a.charAt(i-1)]=i;}return d[n+1][m+1];} }
